insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '238abc7b-4f60-5212-8cce-fa46fd5ac0eb', id, null, 1, '1', 'Completar uma das seguintes tarefas:', '2026-09-24 11:54:01', null from especialidades where codigo = 'EN-052' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '3f7a9576-2712-5354-962a-51d4485a141e', id, '238abc7b-4f60-5212-8cce-fa46fd5ac0eb', 2, '1.a', 'Cuidar de um pequeno mamífero de estimação por, pelo menos, 1 mês. (Cães e gatos não estão incluídos). Antes da compra do animal, pesquisar o seguinte: país de origem, hábitos alimentares (variedades, frequência, quantidade), necessidade de vacinas, doenças mais comuns (que sofre e que pode transmitir ao homem), preço de mercado, necessidade de espaço, necessidade de atenção diária, clínica veterinária especializada mais próxima e estimativa de tempo de vida. Ao final do período, fazer um relatório dos cuidados com seu pequeno animal. Incluir tópicos como alimentos favoritos, sua história preferida sobre o animal, alguns de seus hábitos, horários em que é mais ativo, etc.', '2026-09-24 11:54:01', null from especialidades where codigo = 'EN-052' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'f060849a-2551-5b8a-90f8-fdb7d1aac15b', id, '238abc7b-4f60-5212-8cce-fa46fd5ac0eb', 3, '1.b', 'Se você não possui um pequeno mamífero de estimação, mas já teve um no passado, cuidar do animalzinho de alguém durante, pelo menos, uma semana. Fazer um relatório dos cuidados com os horários de dar água, comida, limpar a gaiola, etc. Incluir em seu relatório um tópico comparando esse animal emprestado ou que criou no passado em termos de horários de maior atividade, espécie e hábitos gerais.', '2026-09-24 11:54:01', null from especialidades where codigo = 'EN-052' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
